import type { Minor } from '../lib/money'
import { caseWeights } from './caseWeights.generated'
import { fixedCaseWeights } from './caseOddsFixed'

export type Rarity = 'common' | 'rare' | 'epic' | 'legendary'

export interface Gift {
  id: string
  name: string
  image: string
  priceMinor: Minor
  rarity: Rarity
  priceSource: 'catalog-config' | 'demo'
  priceUpdatedAt: string
  collection: string
  serialNumber: number | null
  available: boolean
  fragmentFloorTon?: number
  model?: string
  backdrop?: string
  symbol?: string
}

export interface CaseEntry {
  itemId: string
  weight: number
}

export interface CaseDefinition {
  id: string
  name: string
  image: string
  priceMinor: Minor
  freeCooldownMs: number | null
  isNew: boolean
  glow: string
  entries: readonly CaseEntry[]
}

export const RARITY_LABELS: Record<Rarity, string> = {
  common: 'Обычный',
  rare: 'Редкий',
  epic: 'Эпический',
  legendary: 'Легендарный',
}

const PRICE_UPDATED_AT = '2026-10-30T00:00:00Z'

export function nftGift(
  id: string,
  name: string,
  priceMinor: Minor,
  rarity: Rarity,
  collection: string,
  image: string,
  fragmentFloorTon: number,
  model?: string,
  backdrop?: string,
  symbol?: string,
  serialNumber?: number | null,
): Gift {
  return {
    id,
    name,
    // картинки подарков хранятся в WebP (в ~30 раз легче PNG): в каталоге остаются прежние имена .png
    image: image.replace(/\.png$/, '.webp'),
    priceMinor,
    rarity,
    priceSource: 'catalog-config',
    priceUpdatedAt: PRICE_UPDATED_AT,
    collection,
    serialNumber: serialNumber ?? null,
    available: true,
    fragmentFloorTon,
    model,
    backdrop,
    symbol,
  }
}

function gift(
  id: string,
  name: string,
  priceMinor: Minor,
  rarity: Rarity,
  collection: string,
  source: Gift['priceSource'],
  fragmentFloorTon?: number,
): Gift {
  return {
    id,
    name,
    image: `/gifts/${id}.svg`,
    priceMinor,
    rarity,
    priceSource: source,
    priceUpdatedAt: PRICE_UPDATED_AT,
    collection,
    serialNumber: null,
    available: true,
    fragmentFloorTon,
  }
}

/** Приз в TON из кейса: сразу зачисляется на баланс (в инвентарь не попадает). */
export function isTonPrize(giftOrId: Gift | string): boolean {
  const id = typeof giftOrId === 'string' ? giftOrId : giftOrId.id
  return id.startsWith('ton_')
}

function tonPrize(minor: Minor): Gift {
  const ton = minor / 1000
  return {
    id: `ton_${minor}`,
    name: `${ton} TON`,
    // единый значок TON (синий камень с белой искрой) — без подписей на картинке
    image: '/gifts/ton_gem.webp',
    priceMinor: minor,
    rarity: minor >= 25000 ? 'legendary' : minor >= 5000 ? 'epic' : minor >= 2000 ? 'rare' : 'common',
    priceSource: 'catalog-config',
    priceUpdatedAt: PRICE_UPDATED_AT,
    collection: 'TON',
    serialNumber: null,
    available: true,
  }
}

/** Обычный (не NFT) подарок Telegram: прозрачный стикер, цена по курсу Stars (175 Stars = 1 TON). */
function regularGift(id: string, name: string, priceMinor: Minor, file: string): Gift {
  return {
    id,
    name,
    image: `/gifts/png/${file}.webp`,
    priceMinor,
    rarity: priceMinor >= 500 ? 'rare' : 'common',
    priceSource: 'catalog-config',
    priceUpdatedAt: PRICE_UPDATED_AT,
    collection: 'Classic Gifts',
    serialNumber: null,
    available: true,
  }
}

